using Contoso.Scoring;

namespace Contoso.Scoring.Tests;

[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calculator = new();

    // --- CalculatePercentage: boundary & range checks ---

    [TestMethod]
    [DataRow(10, 10, 100.0, DisplayName = "Perfect score")]
    [DataRow(0, 10, 0.0, DisplayName = "Zero correct")]
    [DataRow(5, 10, 50.0, DisplayName = "Half correct")]
    [DataRow(1, 3, 33.333333333333336, DisplayName = "Repeating decimal")]
    public void CalculatePercentage_ValidInputs_ReturnsExpected(int correct, int total, double expected)
    {
        var result = _calculator.CalculatePercentage(correct, total);
        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void CalculatePercentage_Result_IsInValidRange()
    {
        var result = _calculator.CalculatePercentage(7, 10);

        Assert.IsInRange(result, 0.0, 100.0);
        Assert.IsGreaterThan(0.0, result);
        Assert.IsLessThan(100.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_PerfectScore_IsNotGreaterThan100()
    {
        var result = _calculator.CalculatePercentage(10, 10);
        Assert.AreEqual(100.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_ZeroCorrect_ReturnsZero()
    {
        var result = _calculator.CalculatePercentage(0, 10);
        Assert.AreEqual(0.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(0, 0));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(11, 10));
    }

    // --- GetGrade: boundary tests at each threshold ---

    [TestMethod]
    [DataRow(90.0, "A", DisplayName = "Exactly 90 → A")]
    [DataRow(89.9, "B", DisplayName = "Just below 90 → B")]
    [DataRow(80.0, "B", DisplayName = "Exactly 80 → B")]
    [DataRow(79.9, "C", DisplayName = "Just below 80 → C")]
    [DataRow(70.0, "C", DisplayName = "Exactly 70 → C")]
    [DataRow(69.9, "D", DisplayName = "Just below 70 → D")]
    [DataRow(60.0, "D", DisplayName = "Exactly 60 → D")]
    [DataRow(59.9, "F", DisplayName = "Just below 60 → F")]
    [DataRow(0.0, "F", DisplayName = "Zero → F")]
    [DataRow(100.0, "A", DisplayName = "Perfect → A")]
    public void GetGrade_AtBoundaries_ReturnsCorrectGrade(double percentage, string expected)
    {
        var result = _calculator.GetGrade(percentage);
        Assert.AreEqual(expected, result);
    }

    // --- NormalizeScore: range & clamping checks ---

    [TestMethod]
    public void NormalizeScore_MidRange_IsInRange()
    {
        var result = _calculator.NormalizeScore(50.0, 100.0);

        Assert.IsInRange(result, 0.0, 100.0);
        Assert.AreEqual(50.0, result);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_ClampedTo100()
    {
        var result = _calculator.NormalizeScore(150.0, 100.0);
        Assert.AreEqual(100.0, result);
    }

    [TestMethod]
    public void NormalizeScore_ZeroRaw_ReturnsZero()
    {
        var result = _calculator.NormalizeScore(0.0, 100.0);
        Assert.AreEqual(0.0, result);
    }

    [TestMethod]
    public void NormalizeScore_PartialScore_IsGreaterThanZero()
    {
        var result = _calculator.NormalizeScore(25.0, 200.0);

        Assert.IsGreaterThan(0.0, result);
        Assert.IsLessThan(100.0, result);
        Assert.AreEqual(12.5, result);
    }

    [TestMethod]
    public void NormalizeScore_NegativeRawScore_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(-1.0, 100.0));
    }

    [TestMethod]
    public void NormalizeScore_ZeroMaxRaw_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(50.0, 0.0));
    }

    [TestMethod]
    public void NormalizeScore_NegativeMaxRaw_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(50.0, -10.0));
    }
}

